import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/fritzbox-to-mqtt/troubleshooting.md","filePath":"en/projects/fritzbox-to-mqtt/troubleshooting.md","lastUpdated":1793123188000}'),s={name:"en/projects/fritzbox-to-mqtt/troubleshooting.md"};function i(n,e,d,l,h,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="mqtt-reports-not-authorized" tabindex="-1">MQTT Reports <code>Not authorized</code> <a class="header-anchor" href="#mqtt-reports-not-authorized" aria-label="Permalink to &quot;MQTT Reports `Not authorized`&quot;">​</a></h2><p>The app uses the internal MQTT service from Home Assistant. Check:</p><ul><li>Mosquitto broker app installed and started</li><li>MQTT integration configured</li><li>app restarted after Mosquitto became available</li></ul><h2 id="fritz-box-reports-401-unauthorized" tabindex="-1">FRITZ!Box Reports <code>401 Unauthorized</code> <a class="header-anchor" href="#fritz-box-reports-401-unauthorized" aria-label="Permalink to &quot;FRITZ!Box Reports `401 Unauthorized`&quot;">​</a></h2><p>Check the FRITZ!Box username, password and permissions. The user must be allowed to access the required FRITZ!Box data.</p><h2 id="some-values-stay-unknown" tabindex="-1">Some Values Stay <code>unknown</code> <a class="header-anchor" href="#some-values-stay-unknown" aria-label="Permalink to &quot;Some Values Stay `unknown`&quot;">​</a></h2><p>Not every FRITZ!Box exposes every value through the same interfaces. The app tries TR-064, service discovery and web/Lua fallbacks. If a value is missing, enable <code>log_value_details</code> and inspect the relevant log lines.</p><h2 id="port-1012" tabindex="-1">Port <code>1012</code> <a class="header-anchor" href="#port-1012" aria-label="Permalink to &quot;Port `1012`&quot;">​</a></h2><p>Port <code>1012</code> is only the live call monitor. Upload rate, download rate and box status do not come from port <code>1012</code>.</p><h2 id="hacs-does-not-find-the-project" tabindex="-1">HACS Does Not Find The Project <a class="header-anchor" href="#hacs-does-not-find-the-project" aria-label="Permalink to &quot;HACS Does Not Find The Project&quot;">​</a></h2><p>This is expected. The project is a Supervisor app and is installed through the Home Assistant App-Store as a repository, not through HACS.</p>',12)])])}const m=o(s,[["render",i]]);export{p as __pageData,m as default};
